DROP TABLE IF EXISTS `cleaning_requirements`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cleaning_requirements` (
  `id` int NOT NULL AUTO_INCREMENT,
  `cleaning_object_id` int NOT NULL,
  `requirement_type` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `requirement_content` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_by_id` int NOT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `cleaning_requirements_cleaning_object_id_idx` (`cleaning_object_id`),
  KEY `cleaning_requirements_created_by_id_idx` (`created_by_id`),
  CONSTRAINT `cleaning_requirements_cleaning_object_id_fkey` FOREIGN KEY (`cleaning_object_id`) REFERENCES `cleaning_objects` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `cleaning_requirements_created_by_id_fkey` FOREIGN KEY (`created_by_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=124 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
