--
-- Table structure for table `filter_catalogs`
--

DROP TABLE IF EXISTS `filter_catalogs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `filter_catalogs` (
  `id` int NOT NULL AUTO_INCREMENT,
  `filter_code` varchar(50) NOT NULL,
  `filter_type` varchar(100) NOT NULL,
  `usable_steam_cycles` int DEFAULT NULL,
  `description` text,
  `created_by_id` int NOT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `pre_filter_sensory_requirement` text,
  `integrity_requirement` text,
  `post_filter_sensory_requirement` text,
  PRIMARY KEY (`id`),
  UNIQUE KEY `filter_catalogs_filter_code_key` (`filter_code`),
