--
-- Table structure for table `item_equipment`
--

DROP TABLE IF EXISTS `item_equipment`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `item_equipment` (
  `id` int NOT NULL AUTO_INCREMENT,
  `item_code` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `equipment_id` int NOT NULL,
  `created_by_id` int NOT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `item_equipment_item_equipment_key` (`item_code`,`equipment_id`),
  KEY `item_equipment_item_code_idx` (`item_code`),
  KEY `item_equipment_equipment_id_idx` (`equipment_id`),
  KEY `item_equipment_created_by_id_idx` (`created_by_id`),
  CONSTRAINT `item_equipment_created_by_id_fkey` FOREIGN KEY (`created_by_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `item_equipment_equipment_id_fkey` FOREIGN KEY (`equipment_id`) REFERENCES `equipment` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `item_equipment_item_code_fkey` FOREIGN KEY (`item_code`) REFERENCES `items` (`item_code`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=977 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

