DROP TABLE IF EXISTS `item_features`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `item_features` (
  `id` int NOT NULL AUTO_INCREMENT,
  `item_code` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `feature_id` int NOT NULL,
  `enabled` tinyint(1) NOT NULL DEFAULT '1',
  `order` int DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `item_features_item_code_feature_id_key` (`item_code`,`feature_id`),
  KEY `item_features_feature_id_fkey` (`feature_id`),
  KEY `item_features_item_code_fkey` (`item_code`),
  CONSTRAINT `item_features_feature_id_fkey` FOREIGN KEY (`feature_id`) REFERENCES `features` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `item_features_item_code_fkey` FOREIGN KEY (`item_code`) REFERENCES `items` (`item_code`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=8957 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

