INSERT INTO `production_order_deviations` VALUES (9,2125,'Test sai lệch','Huỷ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,158,947,'2026-05-29 07:00:13.636','2026-08-01 07:04:13.730','2026-08-01 07:04:13.728'),(10,2125,'test sai lệch 2','Chấp nhận',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,52,947,'2026-05-29 07:01:12.305','2026-08-01 07:04:08.789','2026-08-01 07:04:08.787'),(11,2618,'Máy rót nhu động thể tích không đều,vẫn trong khoảng cho phép',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,562,'2026-08-11 01:55:22.830','2026-08-11 01:55:22.830',NULL),(12,2683,'Tải 2 nắp tay. Gầm máy line 2 có hiện tượng kêu.',NULL,'theo dõi gầm máy. máy vẫn chạy',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,562,'2026-08-12 03:04:08.779','2026-08-12 08:30:52.279',NULL),(13,2683,'Phát hiện có lọ bị vàng bên trong','loại lọ vàng',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,918,'2026-08-12 08:46:56.470','2026-08-12 08:46:56.470',NULL),(14,2665,'passbox phòng đóng eskar hỏng cửa',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,743,'2026-08-13 06:47:27.271','2026-08-13 06:50:07.074',NULL),(15,2703,'Dùng bộ chai + thay seal xốp bằng 2 seal bóng BB02842 040826 kết quả độ kín không đạt (2/10 chảy ra miệng)','Chấp nhận',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,953,'2026-08-13 07:56:40.448','2026-08-13 07:56:40.448',NULL),(16,2528,'Tải 2 nắp tay',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,562,'2026-08-14 07:19:57.607','2026-08-14 07:19:57.607',NULL),(17,2530,'Tải 2 nắp tay.\nMáy rót bất ổn có lọ không dịch.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,562,'2026-08-15 02:43:50.233','2026-08-15 02:47:45.066',NULL),(18,2674,'BBC1 sau xử lý có cặn đen bên trong','Sục khí nén qua cột 0.22 để đuổi cặn, sau đó ủ Ozone tối thiểu 3 giờ, dịch Vesita đậy bảo quản (t7 đến t2 tuần sau), lọc lại qua cột kép trước khi đóng, trước đóng ủ ozone chai tối thiểu 1 tiếng',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,31,953,'2026-08-15 07:26:18.744','2026-08-15 07:26:18.744',NULL),(19,2698,'Cột lọc dịch đệm test sau lọc không đạt.','Bỏ dịch đệm.\nTiệt trùng lại hệ .\nCân pha lại dịch đệm .',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,918,'2026-08-15 08:15:18.510','2026-08-15 08:15:18.510',NULL),(20,2698,'Máy đóng được ~7000 lọ thì băng tải chạy k đều làm đổ lọ nhiều .','Dừng máy. chỉnh lại băng tải\nLọ đổ rớt dịch . bỏ đi.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,918,'2026-08-15 08:38:02.252','2026-08-15 08:38:02.252',NULL),(21,2681,'Tải 2 nắp tay.\nTrục rót dịch bị giật.\nGầm máy line 2 có hiện tượng kêu to',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,562,'2026-08-17 02:07:58.488','2026-08-17 04:53:14.865',NULL),(22,2681,'Laf di động chuyển vào khu C bị bẩn','báo quản đốc cho vệ sinh lại',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,918,'2026-08-17 04:18:07.978','2026-08-17 04:18:07.978',NULL),(23,2685,'Tải 2 nắp tay.\nTrục rót dịch bị giật mạnh.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,562,'2026-08-18 01:39:02.935','2026-08-18 01:39:02.935',NULL),(24,2712,'Chưa áp dụng phương pháp lọc liên tiếp qua 2 cột lọc liên tiếp\nChuyển dịch từ tank pha -> qua cột-> tank phụ (đã tiệt trùng)-> qua cột->tank chứa (đã tiệt trùng)->vào máy đóng','Chấp nhận \nVệ sinh tank pha 150L (không tiệt trùng) để pha tiếp lô tiếp theo \n2 tank phụ+ tank chứa: tiệt trùng lại',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,953,940,'2026-08-18 07:12:31.051','2026-08-18 07:12:31.051',NULL),(25,2712,'Nl Polyquaternium được cân từ hôm trước để pha. nhưng máy đóng hỏng. dừng pha','chuyển ra kho để bảo quản',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,918,'2026-08-18 07:58:50.665','2026-08-18 07:58:50.665',NULL),(26,2712,'Máy đóng line 1 băng tải chạy k đều,dừng nhiều.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,550,'2026-08-18 08:13:01.670','2026-08-18 08:43:47.338',NULL),(27,2722,'Tải 2 nắp tay.\nTrục rót dịch lắc mạnh',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,562,'2026-08-19 01:23:00.325','2026-08-19 01:23:00.325',NULL),(28,2710,'Chỉ số Car không đạt',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,604,'2026-08-19 02:17:33.947','2026-08-19 02:17:33.947',NULL),(29,2705,'Sai thứ tự pha chế: phối tinh dầu vào tween rồi cho vào tank pha. Theo phiếu pha sau phối tinh dầu+tween với lần lượt PG, HPMC sau ngâm mới cho vào tank pha chế','Khuấy tiếp hỗn hợp trong tank pha thêm 15p. tuần hoàn 3 lần, mỗi lần 15s và kiểm tra dịch đồng nhất, không tách lớp',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,940,'2026-08-19 07:26:22.731','2026-08-19 07:26:22.731',NULL),(30,2714,'Thay đổi phương pháp lọc: lọc liên tiếp 2 cột kép qua máy đóng\nSau khi lọc khoảng 50L dịch thì dịch chảy chậm hơn, nhưng vẫn lọc tiếp được. Thời gian lọc từ 8h-10h',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,940,'2026-08-19 07:28:48.381','2026-08-19 07:28:48.381',NULL),(31,2724,'Tải 2 nắp tay.\nTrục rót dịch lắc mạnh',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,562,'2026-08-20 01:04:29.474','2026-08-20 01:04:29.474',NULL),(32,2705,'Tải 1,2 dáy lọ bẩn do khay','Lau lại',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1057,'2026-08-20 03:58:27.388','2026-08-20 03:58:27.388',NULL),(33,2720,'HPMC E4M khi rắc 1/2 lượng vào tank thì phát hiện dịch trong tank tạo bọt nhiều trên bề mặt. Lượng NL còn lại trong bình Schott cho thêm nước nóng 70 độ vào thì NL trương nở nhiều => không đổ dịch ra được bình','Hủy dịch và nguyên liệu => Cân và pha lại \nTank 150 rửa 5 lần nước nóng và ủ cồn 1 giờ trước khi sử dụng',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,940,'2026-08-20 04:39:39.853','2026-08-20 04:39:39.853',NULL),(34,2720,'Tank chứa dịch bên line 1, dẫn dich từ line 1 sang line line 2 đóng.\nKhay 1 thể tích không ổn định','Cân lại BTP theo khoảng kiểm soát khối lượng 13.3-13.76g','Đã loại 80 lọ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,562,'2026-08-21 08:22:04.335','2026-08-22 09:17:49.021',NULL),(35,2720,'Máy bỏ nút nhiều, nhiều lọ không nút bỏ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,942,'2026-08-21 08:45:27.157','2026-08-21 08:45:27.157',NULL),(36,2720,'Thể tích 2 lọ liên tiếp không bằng nhau nhưng vẫn trong khoảng kiểm soát',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,942,'2026-08-21 08:46:31.025','2026-08-21 08:46:31.025',NULL),(37,2730,'Tải 2 nắp tay',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,562,'2026-08-22 01:31:47.043','2026-08-22 01:31:47.043',NULL),(38,2764,'Dùng khối lượng gừng tươi 24,7kg ( yêu cầu 25kg)','Chấp nhận',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1015,612,'2026-08-22 07:55:28.185','2026-08-22 07:55:28.185',NULL),(39,2730,'Tải 32 nắp tay',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,562,'2026-08-22 10:46:22.542','2026-08-22 10:46:22.542',NULL),(40,2764,'Dịch chiết gừng lọc qua cột 0,22 mcm bị tắc, mất nhiều thời gian lọc','Vẫn tiến hành lọc, rửa cột bằng nước RO1 qua lọc , lọc tiếp',NULL,NULL,'Nguyên vật liệu',NULL,NULL,NULL,NULL,NULL,NULL,NULL,1004,'2026-08-24 08:50:29.475','2026-08-24 09:02:28.551',NULL),(41,2748,'Đèn phòng pha chế 2c cháy 1 bóng.\nCánh khuấy tank 1000L kêu két.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1057,'2026-08-24 09:12:38.825','2026-08-24 09:12:38.825',NULL);
