INSERT INTO `production_order_filtration_checks` VALUES (1,2685,'Sau tank pha',123,'Độ sạch trực quan: Tuyệt đối không có bất kỳ dị vật, bụi bẩn, sợi tơ, vết ố hay tiểu phân lạ nào bám trên toàn bộ bề mặt lõi lọc. Gioăng cao su: Vòng O-ring phải nằm đúng vị trí, không bị đứt, xước xát, dập nát hay biến dạng. Tính nguyên vẹn: Khung nhựa bảo vệ bên ngoài, lõi trung tâm và hai đầu cap không có vết nứt, vỡ hay biến dạng. Lớp màng lọc xếp nếp bên trong không bị dập, rách hay có màu sắc bất thường.','Đạt','Độ sút áp < 45.1 mbar trong 3 phút','44,7',940,NULL,'2026-08-18 01:13:00.000','2026-08-18 01:50:00.000',743,0.500,'Độ sút áp < 45.1 mbar trong 3 phút','38,1','Độ sạch trực quan: Tuyệt đối không có bất kỳ dị vật, bụi bẩn, sợi tơ, vết ố hay tiểu phân lạ nào bám trên toàn bộ bề mặt lõi lọc. Gioăng cao su: Vòng O-ring phải nằm đúng vị trí, không bị đứt, xước xát, dập nát hay biến dạng. Tính nguyên vẹn: Khung nhựa bảo vệ bên ngoài, lõi trung tâm và hai đầu cap không có vết nứt, vỡ hay biến dạng. Lớp màng lọc xếp nếp bên trong không bị dập, rách hay có màu sắc bất thường.','Đạt',743,'2026-08-07 08:35:17.998','2026-08-18 08:09:42.198'),(2,2685,'Sau tank chứa',NULL,NULL,NULL,NULL,NULL,940,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-08-07 08:35:25.757','2026-08-07 08:35:25.757'),(6,2661,'Sau tank pha',22,'Độ sạch trực quan: Tuyệt đối không có bất kỳ dị vật, bụi bẩn, sợi tơ, vết ố hay tiểu phân lạ nào bám trên toàn bộ bề mặt lõi lọc. Gioăng cao su: Vòng O-ring phải nằm đúng vị trí, không bị đứt, xước xát, dập nát hay biến dạng. Tính nguyên vẹn: Khung nhựa bảo vệ bên ngoài, lõi trung tâm và hai đầu cap không có vết nứt, vỡ hay biến dạng. Lớp màng lọc xếp nếp bên trong không bị dập, rách hay có màu sắc bất thường.','Đạt','Độ sút áp < 45.1 mbar trong 3 phút','39,2',743,1.000,'2026-08-11 01:16:00.000','2026-08-11 01:55:00.000',743,0.500,'Độ sút áp < 45.1 mbar trong 3 phút','37,5','Độ sạch trực quan: Tuyệt đối không có bất kỳ dị vật, bụi bẩn, sợi tơ, vết ố hay tiểu phân lạ