--
-- Table structure for table `production_order_leak_tightness_checks`
--

DROP TABLE IF EXISTS `production_order_leak_tightness_checks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `production_order_leak_tightness_checks` (
  `id` int NOT NULL AUTO_INCREMENT,
  `production_order_id` int NOT NULL,
  `requirement` text COLLATE utf8mb4_unicode_ci,
  `dosage_form_stage` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `unit_1_result` tinyint(1) NOT NULL,
  `unit_2_result` tinyint(1) DEFAULT NULL,
  `unit_3_result` tinyint(1) DEFAULT NULL,
  `unit_4_result` tinyint(1) DEFAULT NULL,
  `unit_5_result` tinyint(1) DEFAULT NULL,
  `unit_6_result` tinyint(1) DEFAULT NULL,
  `unit_7_result` tinyint(1) DEFAULT NULL,
  `unit_8_result` tinyint(1) DEFAULT NULL,
  `unit_9_result` tinyint(1) DEFAULT NULL,
  `unit_10_result` tinyint(1) DEFAULT NULL,
  `created_by_id` int NOT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
