DROP TABLE IF EXISTS `production_order_vial_inspection_checks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `production_order_vial_inspection_checks` (
  `id` int NOT NULL AUTO_INCREMENT,
  `production_order_id` int NOT NULL,
  `bag_number` int NOT NULL,
  `fiber_vial_count` int NOT NULL,
  `particulate_count` int NOT NULL,
  `damaged_count` int NOT NULL,
  `other_defect_count` int NOT NULL,
  `note` text COLLATE utf8mb4_unicode_ci,
  `created_by_id` int NOT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `po_vial_inspection_checks_po_id_fkey` (`production_order_id`),
  KEY `po_vial_inspection_checks_created_by_id_fkey` (`created_by_id`),
  CONSTRAINT `po_vial_inspection_checks_created_by_id_fkey` FOREIGN KEY (`created_by_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `po_vial_inspection_checks_po_id_fkey` FOREIGN KEY (`production_order_id`) REFERENCES `production_orders` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=47 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

