DROP TABLE IF EXISTS `production_order_volume_checks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `production_order_volume_checks` (
  `id` int NOT NULL AUTO_INCREMENT,
  `production_order_id` int NOT NULL,
  `package_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `requirement` text COLLATE utf8mb4_unicode_ci,
  `dosage_form_stage` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `unit_1_volume` decimal(10,2) NOT NULL,
  `unit_2_volume` decimal(10,2) DEFAULT NULL,
  `unit_3_volume` decimal(10,2) DEFAULT NULL,
  `unit_4_volume` decimal(10,2) DEFAULT NULL,
  `unit_5_volume` decimal(10,2) DEFAULT NULL,
  `unit_6_volume` decimal(10,2) DEFAULT NULL,
  `unit` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ml',
  `created_by_id` int NOT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `po_volume_checks_po_id_fkey` (`production_order_id`),
  KEY `po_volume_checks_created_by_id_fkey` (`created_by_id`),
  CONSTRAINT `po_volume_checks_created_by_id_fkey` FOREIGN KEY (`created_by_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `po_volume_checks_po_id_fkey` FOREIGN KEY (`production_order_id`) REFERENCES `production_orders` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=338 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
