  `unit` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `deleted_at` datetime(3) DEFAULT NULL,
  `product_line_id` int DEFAULT NULL,
  `dosage_form_id` int DEFAULT NULL,
  `spray_dose_lower_allowed_limit` decimal(18,6) DEFAULT NULL,
  `spray_dose_upper_allowed_limit` decimal(18,6) DEFAULT NULL,
  `spray_dose_lower_control_limit` decimal(18,6) DEFAULT NULL,
  `spray_dose_upper_control_limit` decimal(18,6) DEFAULT NULL,
  `film_coated_tablet_weight_lower_control_limit` decimal(18,6) DEFAULT NULL,
  `film_coated_tablet_weight_upper_control_limit` decimal(18,6) DEFAULT NULL,
  `film_coated_tablet_weight_lower_allowed_limit` decimal(18,6) DEFAULT NULL,
  `film_coated_tablet_weight_upper_allowed_limit` decimal(18,6) DEFAULT NULL,
  `film_coated_tablet_weight_unit` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `hardness_lower_control_limit` decimal(18,6) DEFAULT NULL,
  `hardness_upper_control_limit` decimal(18,6) DEFAULT NULL,
  `hardness_lower_allowed_limit` decimal(18,6) DEFAULT NULL,
  `hardness_upper_allowed_limit` decimal(18,6) DEFAULT NULL,
  `hardness_unit` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'N',
