INSERT INTO `secondary_packaging_stage_requirements` VALUES (1,'Đóng hộp','- Tần suất: 10 hộp/lần x 60 phút/lần\n- Hộp: Đúng số lô, NSX, HSD. Không bẩn, rách, dính keo. Đồng nhất màu sắc giữa các hộp\n- Đơn: Không bẩn, nhăn, rách, lệch. Đóng thông tin về sản phẩm, rõ nét\n- Tem: Không mất thông tin hộp\n- Quy cách: Đủ số gói, silicagel, đủ khối lượng',947,'2026-08-16 11:17:28.952','2026-08-16 11:17:28.952'),(2,'Đóng thùng','- Yêu cầu: Kiểm tra 5 thùng/lô\n- Nhãn thùng: đúng tên sp, số lô, NSX, HSD, dán không lệch\n- Thùng: Không rách, bẩn, mốc, đúng loại\n- Quy cách: đủ số lượng hộp trong thùng',947,'2026-08-16 11:19:10.277','2026-08-16 11:19:10.277'),(3,'Dán nhãn','- Tần suất: Với dán nhãn máy: IPC kiểm tra 5 lọ mỗi cuộn nhãn trước khi dán hàng loạt. Với dán nhãn thủ công: kiểm tra 10 lọ/lần x 60 phút/lần\nYêu cầu:\n+ Lọ BTP: sạch, khô, không dính dịch hoặc bụi bẩn. Đầu xịt được xoáy chặt, ngay ngắn, không bị móp méo, cong vênh.\n+ Nhãn: Đúng số lô, NSX, HSD. Không vết bẩn, vết keo. Thông tin in rõ ràng, dễ đọc. Màu sắc đồng đều giữa các nhãn. 2 mép nhãn không lệch quá 1 mm.',947,'2026-08-16 11:20:52.045','2026-08-16 11:20:52.045'),(4,'Đóng túi nhôm','- Tần suất: IPC kiểm tra 10 hộp/lần x 60 phút/lần\n- Yêu cầu:\n+ Túi nhôm: Đầy đủ thông tin theo yêu cầu\n+ Túi nhôm được hàn kín, mép hàn không bị nhăn\n+ Quy cách túi nhôm:\n *  PP đếm: Đủ số lượng gói và silicagel theo yêu cầu\n* PP cân: Đủ số lượng theo yêu cầu',947,'2026-08-16 11:23:25.377','2026-08-16 11:23:25.377');
/*!40000 ALTER TABLE `secondary_packaging_stage_requirements` ENABLE KEYS */;
UNLOCK TABLES;

