--
-- Table structure for table `user_login_sessions`
--

DROP TABLE IF EXISTS `user_login_sessions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user_login_sessions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `token_id` int DEFAULT NULL,
  `session_key` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `login_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `logout_at` datetime(3) DEFAULT NULL,
  `last_activity_at` datetime(3) DEFAULT NULL,
  `logout_reason` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_agent` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `user_login_sessions_session_key_key` (`session_key`),
  KEY `user_login_sessions_user_login_at_idx` (`user_id`,`login_at`),
  KEY `user_login_sessions_open_session_idx` (`user_id`,`logout_at`),
  KEY `user_login_sessions_token_id_idx` (`token_id`),
  CONSTRAINT `user_login_sessions_token_id_fkey` FOREIGN KEY (`token_id`) REFERENCES `tokens` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `user_login_sessions_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=191 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `user_login_sessions`
--

LOCK TABLES `user_login_sessions` WRITE;
/*!40000 ALTER TABLE `user_login_sessions` DISABLE KEYS */;
